import crypto from 'node:crypto'

export interface ConnectorConfig {
  githubWebhookSecret: string
  linearApiKey: string
  linearTriageTeamId: string
  fetch?: typeof fetch
}

export interface GitHubIssuePayload {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{
      id: number
      node_id: string
      url: string
      name: string
      color: string
      default: boolean
      description: string | null
    }>
    user: {
      login: string
    }
    html_url: string
  }
  repository: {
    full_name: string
  }
}

export interface LinearIssueCreateResult {
  success: boolean
  issue: {
    id: string
    title: string
    description: string
  }
}

export interface HandleResult {
  linearIssueId: string
  linearIssueTitle: string
  linearIssueDescription: string
}

function verifySignature(payload: string, signature: string, secret: string): boolean {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex')
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
}

function buildGraphQLMutation(title: string, description: string, teamId: string): string {
  const escapedTitle = title.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  const escapedDescription = description.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  return `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${teamId}" }) { success issue { id title description } } }`
}

export async function handle(payload: GitHubIssuePayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.action) {
    throw new Error('Missing required field: action')
  }
  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Only 'labeled' is handled.`)
  }
  if (!payload.issue) {
    throw new Error('Missing required field: issue')
  }
  if (!payload.issue.title) {
    throw new Error('Missing required field: issue.title')
  }
  if (!payload.issue.user?.login) {
    throw new Error('Missing required field: issue.user.login')
  }
  if (!payload.issue.html_url) {
    throw new Error('Missing required field: issue.html_url')
  }

  const hasBugLabel = payload.issue.labels?.some(label => label.name === 'bug')
  if (!hasBugLabel) {
    throw new Error('Issue does not have the "bug" label')
  }

  const title = payload.issue.title
  const description = payload.issue.body ?? ''
  const author = payload.issue.user.login
  const url = payload.issue.html_url

  const mutation = buildGraphQLMutation(title, description, config.linearTriageTeamId)

  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.linearApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query: mutation }),
  })

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
  }

  const data = await response.json() as { data?: { issueCreate?: LinearIssueCreateResult } }

  if (!data.data?.issueCreate?.success) {
    throw new Error('Linear issue creation failed: success is false')
  }

  const issue = data.data.issueCreate.issue
  return {
    linearIssueId: issue.id,
    linearIssueTitle: issue.title,
    linearIssueDescription: issue.description,
  }
}

